511	// TODO: The mapping from workspace root paths to git repositories needs a
512	// unified approach across the codebase: this function, `AgentPanel::classify_worktrees`,
513	// thread persistence (which PathList is saved to the database), and thread
514	// querying (which PathList is used to read threads back). All of these need
515	// to agree on how repos are resolved for a given workspace, especially in
516	// multi-root and nested-repo configurations.
517	fn root_repository_snapshots(
518	    workspace: &Entity<Workspace>,
519	    cx: &App,
520	) -> impl Iterator<Item = project::git_store::RepositorySnapshot> {
521	    let path_list = workspace_path_list(workspace, cx);
522	    let project = workspace.read(cx).project().read(cx);
523	    project.repositories(cx).values().filter_map(move |repo| {
524	        let snapshot = repo.read(cx).snapshot();
525	        let is_root = path_list
526	            .paths()
527	            .iter()
528	            .any(|p| p.as_path() == snapshot.work_directory_abs_path.as_ref());
529	        is_root.then_some(snapshot)
530	    })
