997	                            | project::git_store::RepositoryEvent::HeadChanged,
998	                        _,
999	                    )
1000	                ) {
1001	                    this.schedule_update_entries(false, cx);
1002	                }
1003	            },
1004	        )
1005	        .detach();
1006	
1007	        cx.subscribe_in(
1008	            workspace,
1009	            window,
1010	            move |this, workspace, event: &workspace::Event, window, cx| {
1011	                if let workspace::Event::PanelAdded(view) = event {
1012	                    if let Ok(agent_panel) = view.clone().downcast::<AgentPanel>() {
1013	                        this.subscribe_to_agent_panel(workspace, &agent_panel, window, cx);
1014	                        this.schedule_update_entries(false, cx);
1015	                    }
1016	                }
1017	            },
1018	        )
1019	        .detach();
1020	
1021	        self.observe_docks(workspace, cx);
1022	
1023	        if let Some(agent_panel) = workspace.read(cx).panel::<AgentPanel>(cx) {
1024	            self.subscribe_to_agent_panel(workspace, &agent_panel, window, cx);
1025	        }
