1028	    fn move_entry_paths(
1029	        &mut self,
1030	        project: &Entity<project::Project>,
1031	        old_paths: &WorktreePaths,
1032	        cx: &mut Context<Self>,
1033	    ) {
1034	        if project.read(cx).is_via_collab() {
1035	            return;
1036	        }
1037	
1038	        let new_paths = project.read(cx).worktree_paths(cx);
1039	        let old_folder_paths = old_paths.folder_path_list().clone();
1040	
1041	        let added_pairs: Vec<_> = new_paths
1042	            .ordered_pairs()
1043	            .filter(|(main, folder)| {
1044	                !old_paths
1045	                    .ordered_pairs()
1046	                    .any(|(old_main, old_folder)| old_main == *main && old_folder == *folder)
1047	            })
1048	            .map(|(m, f)| (m.clone(), f.clone()))
1049	            .collect();
1050	
1051	        let new_folder_paths = new_paths.folder_path_list();
1052	        let removed_folder_paths: Vec<PathBuf> = old_folder_paths
1053	            .paths()
1054	            .iter()
1055	            .filter(|p| !new_folder_paths.paths().contains(p))
1056	            .cloned()
1057	            .collect();
1058	
1059	        if added_pairs.is_empty() && removed_folder_paths.is_empty() {
1060	            return;
1061	        }
1062	
1063	        let remote_connection = project.read(cx).remote_connection_options(cx);
1064	        let apply_path_changes = |paths: &mut WorktreePaths| {
1065	            for (main_path, folder_path) in &added_pairs {
1066	                paths.add_path(main_path, folder_path);
1067	            }
1068	            for path in &removed_folder_paths {
1069	                paths.remove_folder_path(path);
1070	            }
1071	        };
1072	        ThreadMetadataStore::global(cx).update(cx, |store, store_cx| {
1073	            store.change_worktree_paths(
1074	                &old_folder_paths,
1075	                remote_connection.as_ref(),
1076	                &apply_path_changes,
1077	                store_cx,
1078	            );
1079	        });
1080	        TerminalThreadMetadataStore::global(cx).update(cx, |store, store_cx| {
1081	            store.change_worktree_paths(
1082	                &old_folder_paths,
1083	                remote_connection.as_ref(),
1084	                &apply_path_changes,
1085	                store_cx,
1086	            );
1087	        });
1088	    }
